    assert.ok(idx > 0, '應找到 DOMContentLoaded');
    // 抓緊接著 800 chars 內的內容
    var block = IDX.substring(idx, idx + 1500);
    assert.ok(block.includes('_globalDragBound = true'),
        'DOMContentLoaded 內應有 _globalDragBound 設定');
